REVISIONS=[
 dict(concept='drinfeld-center',changes=dict(title='Drinfeld center of a monoidal category',description='For a monoidal category C, its center Z(C) has objects (X,c), where c is a half-braiding on X, and morphisms f:X→X′ compatible with the half-braidings. Tensoring these pairs makes Z(C) braided; C itself need not be braided.'),reason='Specify the monoidal input and distinguish it from the braided structure on the output.'),
 dict(concept='monoidal-category',changes=dict(description='A category C with a tensor bifunctor C×C→C, a unit object, and natural associativity and unit isomorphisms satisfying the pentagon and triangle identities.'),reason='Make the bifunctor and natural-isomorphism prerequisites explicit.'),
 dict(concept='half-braiding',changes=dict(description='For an object X of a monoidal category C, a natural family of isomorphisms c_Y:X⊗Y→Y⊗X, compatible with tensor products and the unit: c_{Y⊗Z}=(id_Y⊗c_Z)∘(c_Y⊗id_Z), with associators inserted.'),reason='State the half-braiding convention and include unit compatibility.')]


def source_record(slug,title,authors,year,url,coverage,summary):
    p=ROOT/'references'/f'{slug}.pdf'
    return dict(slug=slug,title=title,authors=authors,year=year,field='Probability' if slug==PROB else 'Real analysis / foundations',
        status='catalogued',coverage=coverage,summary=summary,dependency_review='Learning reference only; no strict research-source dependency is asserted.',
        identifiers=[['url',url]],artifacts=[dict(url=url,version='Version 5, January 11, 2019' if slug==PROB else 'Version 6.3, May 15, 2026',
        accessed_at='2026-11-12',sha256=hashlib.sha256(p.read_bytes()).hexdigest(),local_path=str(p.relative_to(ROOT)),note='Located excerpts inspected for the recursive prerequisite experiment; full-source ingestion is not claimed.')])


def main():
    sources=[source_record(PROB,'Probability: Theory and Examples',['Rick Durrett'],2019,'https://sites.math.duke.edu/~rtd/PTE/PTE5_011119.pdf',
        'Chapter 1, §§1.1–1.4 and §1.6: spaces, measurability, integration, expectation and tail inequalities.',
        'A measure-theoretic learning reference for the Chebyshev prerequisite experiment.'),
        source_record(BASIC,'Basic Analysis I: Introduction to Real Analysis',['Jiří Lebl'],2026,'https://www.jirka.org/ra/realanal.pdf',
        '§0.3, §§1.1–1.4, and §§2.1/2.5: elementary sets and functions, ordered fields, real numbers, sequences and series.',
        'A learning reference for elementary prerequisites shared by the two recursive experiments.')]
    dependencies=[]
    for r in REVIEWS.values():
        for parent in r['parents']:
            dependencies.append(dict(prerequisite=parent,dependent=r['concept'],basis='both',source=r['source'],locator=r['locator'],
                rationale=f"{r['concept']} requires {parent} in the selected definition or proof. "+r['note']))
    links=[dict(source=r['source'],concept=r['concept'],role=r['role'],locator=r['locator'],note='Selected learning reference for a recursive prerequisite review. '+r['note']) for r in REVIEWS.values()]
    plan=dict(roots=['drinfeld-center','chebyshev-inequality'],baseline='Sets, natural numbers, elementary logic and finite arithmetic are primitive vocabulary. Recursion expands every other recorded prerequisite; formal set-theoretic encodings, ZFC axioms, and size foundations for large categories are not part of this pedagogical route.',
        primitives=['set','natural-number'],batch=dict(sources=sources,concepts=NEW,dependencies=dependencies,source_concepts=links,
        note='Two recursive prerequisite experiments: Drinfeld centers and Chebyshev’s inequality. Learning sources do not create strict source-dependency edges.'),
        revisions=REVISIONS,remove_dependencies=[dict(prerequisite='integer',dependent=slug,reason='Natural-number indexing, rather than the integers as an ordered ring, is sufficient for this definition.') for slug in ['real-sequence','nonnegative-series']],
        reviews=list(REVIEWS.values()))
    (ROOT/'data/recursive-expansion.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps(dict(new_concepts=len(NEW),reviewed_concepts=len(REVIEWS),candidate_edges=len(dependencies))))


if __name__=='__main__':main()
